BEGIN;
ALTER TABLE user_roles ADD COLUMN additional_permissions text[] NOT NULL DEFAULT '{}',
  ADD COLUMN qualification_reference text,
  ADD COLUMN responsible_professional boolean NOT NULL DEFAULT false;
ALTER TABLE user_roles ADD CONSTRAINT professional_lead_store_required CHECK (NOT responsible_professional OR store_id IS NOT NULL);
CREATE UNIQUE INDEX one_professional_lead_per_store ON user_roles(store_id) WHERE responsible_professional;
SELECT 'LEGACY_SALES_ROLE_RETIRED', 'user', ur.user_id::text,
 jsonb_build_object('roleCode', r.code, 'storeId', ur.store_id),
 'Vai trò ngừng dùng. Cần kiểm tra chuyên môn trước khi gán Dược sĩ; không tự động nâng quyền.'
FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE r.code='sales_staff';
UPDATE refresh_sessions SET revoked_at=now(), revoked_reason='ROLE_MODEL_CHANGED' WHERE revoked_at IS NULL;
DELETE FROM user_roles WHERE role_id IN (SELECT id FROM roles WHERE code='sales_staff');
DELETE FROM role_permissions WHERE role_id IN (SELECT id FROM roles WHERE code='sales_staff');
DELETE FROM roles WHERE code='sales_staff';
UPDATE roles SET name='Chủ nhà thuốc, quản lý' WHERE code='admin';
DELETE FROM role_permissions WHERE role_id IN (SELECT id FROM roles WHERE code='admin');
UPDATE roles SET name='Dược sĩ' WHERE code='pharmacist';
DELETE FROM role_permissions WHERE role_id IN (SELECT id FROM roles WHERE code='pharmacist');
UPDATE roles SET name='Nhân viên kho' WHERE code='warehouse_staff';
DELETE FROM role_permissions WHERE role_id IN (SELECT id FROM roles WHERE code='warehouse_staff');
UPDATE roles SET name='Kiểm toán, chỉ đọc' WHERE code='auditor';
DELETE FROM role_permissions WHERE role_id IN (SELECT id FROM roles WHERE code='auditor');
UPDATE settings SET value=value - 'sales_staff' WHERE key='discountLimitPercent' AND jsonb_typeof(value)='object';
COMMIT;
